+    assert_eq!(gone["workholding"][0]["fixtures"], json!([]), "{gone}");
+    let job = c.ok("get_job", json!({}));
+    assert!(job["models"].as_array().is_some_and(|m| m.iter().any(|m| m["name"] == json!("vise") && m["fixture"] == json!(false))), "{job}");
+    let _ = std::fs::remove_dir_all(&dir);
+}
